def __enter__(self) -> "LangWatchSpan":
    """Makes the span usable as a context manager."""
    self.trace = self.trace or langwatch.telemetry.context.get_current_trace(
        suppress_warning=True, start_if_none=True
    )
    if not self.ignore_missing_trace_warning and not self.trace and not self.parent:
        warn("No current trace found, some spans may not be sent to LangWatch")

    self._create_span()
    self.span = cast(
        Type["LangWatchSpan"],
        lambda **kwargs: LangWatchSpan(
            trace=self.trace
            or langwatch.telemetry.context.get_current_trace(
                suppress_warning=True, start_if_none=True
            ),
            **kwargs,
        ),
    )

    return self

def __exit__(
    self,
    exc_type: Optional[type],
    exc_value: Optional[BaseException],
    traceback: Any,
) -> bool:
    """Exit the span context, recording any errors that occurred."""
    try:
        # Fix: Check if exc_value is an Exception before recording
        if exc_value is not None and isinstance(exc_value, Exception):
            self.record_error(exc_value)
    except Exception as e:
        warn(f"Failed to exit LangWatch span: {e}")
    finally:
        self._cleanup(exc_type, exc_value, traceback)
    return False  # Don't suppress exceptions

async def __aenter__(self) -> "LangWatchSpan":
    """Makes the span usable as an async context manager."""
    self.trace = self.trace or langwatch.telemetry.context.get_current_trace(
        suppress_warning=True, start_if_none=True
    )
    if not self.ignore_missing_trace_warning and not self.trace and not self.parent:
        warn("No current trace found, some spans may not be sent to LangWatch")

    self._create_span()

import asyncio
import threading
from typing import TYPE_CHECKING, Dict, List
import contextvars
import warnings
from opentelemetry import trace as trace_api
from opentelemetry import context

from langwatch.utils.initialization import ensure_setup

if TYPE_CHECKING:
    from langwatch.telemetry.span import LangWatchSpan
    from langwatch.telemetry.tracing import LangWatchTrace

stored_langwatch_trace = contextvars.ContextVar["LangWatchTrace"](
    "stored_langwatch_trace"
)
main_thread_langwatch_trace: List["LangWatchTrace"] = []

stored_langwatch_span = contextvars.ContextVar["LangWatchSpan"]("stored_langwatch_span")
main_thread_langwatch_span: List["LangWatchSpan"] = []


def get_current_trace(
    suppress_warning: bool = False, start_if_none: bool = False
) -> "LangWatchTrace":
    """Get the current trace from the LangWatch context.

    Returns:
        A LangWatchTrace.
    """
    ensure_setup()
    trace = stored_langwatch_trace.get(None)
    if trace is not None:
        return trace

    if (
        _is_on_child_thread()
        and not _is_on_async_loop()
        and len(main_thread_langwatch_trace) > 0
    ):
        return main_thread_langwatch_trace[-1]

    from langwatch.telemetry.tracing import LangWatchTrace

    if not suppress_warning:
        warnings.warn(
            "No trace in context when calling langwatch.get_current_trace(), perhaps you forgot to use @langwatch.trace()?",
        )

    trace = LangWatchTrace()
    if start_if_none:
        otel_span = trace_api.get_current_span()
        otel_span_id = otel_span.get_span_context().span_id
        trace.__enter__()

        # Keep the previous span in the context if we are starting a new trace not at root level
        if otel_span_id != 0:
            ctx = trace_api.set_span_in_context(otel_span)
            context.attach(ctx)
        otel_span = trace_api.get_current_span()

        trace.__exit__(None, None, None)

        return trace
    return trace


def get_current_span() -> "LangWatchSpan":
    """Get the current span from the LangWatch context.
    If no span exists in LangWatch context, falls back to OpenTelemetry context.

    Returns:
        A LangWatchSpan.
    """
    ensure_setup()

    otel_span = trace_api.get_current_span()
    otel_span_id = otel_span.get_span_context().span_id

    # If on a child thread and there is no parent, try to find a parent from the main thread
    if (
        _is_on_child_thread()
        and not _is_on_async_loop()
        and len(main_thread_langwatch_span) > 0
        and otel_span_id == 0
    ):
        return main_thread_langwatch_span[-1]

    from langwatch.telemetry.span import LangWatchSpan

    trace = get_current_trace()
    return LangWatchSpan.wrap_otel_span(otel_span, trace)


def _set_current_trace(trace: "LangWatchTrace"):
    global main_thread_langwatch_trace
    # Only touch the main-thread global fallback in the pure-threading path.
    # In async mode, every asyncio.Task gets its own contextvar copy; the
    # shared list would leak traces between concurrent sibling tasks.
    if not _is_on_child_thread() and not _is_on_async_loop():
        main_thread_langwatch_trace.append(trace)

    try:
        return stored_langwatch_trace.set(trace)
    except Exception as e:
        warnings.warn(f"Failed to set LangWatch trace context: {e}")
        return None


def _set_current_span(span: "LangWatchSpan"):
    global main_thread_langwatch_span
    if not _is_on_child_thread() and not _is_on_async_loop():
        main_thread_langwatch_span.append(span)

    # Dummy token, just for the main thread span list
    return "token"


def _reset_current_trace(token: contextvars.Token):
    global main_thread_langwatch_trace
    if not _is_on_child_thread() and not _is_on_async_loop():
        if len(main_thread_langwatch_trace) > 0:
            main_thread_langwatch_trace.pop()

    try:
        stored_langwatch_trace.reset(token)
    except Exception as e:
        # Only warn if it's not a context error
        if "different Context" not in str(e):
            warnings.warn(f"Failed to reset LangWatch trace context: {e}")


def _reset_current_span(_token: str):
    global main_thread_langwatch_span
    if not _is_on_child_thread() and not _is_on_async_loop():
        if len(main_thread_langwatch_span) > 0:
            main_thread_langwatch_span.pop()


def _is_on_child_thread() -> bool:
    return threading.current_thread() != threading.main_thread()


def _is_on_async_loop() -> bool:
    """True when called from inside a running asyncio event loop.

    In async mode, ``asyncio.Task`` copies contextvars per task, so the
    ``main_thread_langwatch_*`` global fallbacks are both redundant and
    dangerous — two sibling tasks on the same thread would pollute each
    other via the shared list.
    """
    try:
        asyncio.get_running_loop()
        return True
    except RuntimeError:
        return False

def flush_on_exit(self) -> bool:
    """Get the flush on exit flag for the client."""
    return Client._flush_on_exit

@property
def api_key(self) -> str:
    """Get the API key for the client."""
    return Client._api_key

@api_key.setter
def api_key(self, value: str) -> None:
    """Set the API key for the client."""
    if value == Client._api_key:
        return

    previous_key = Client._api_key
    Client._api_key = value

    if previous_key and not Client._skip_open_telemetry_setup:
        self.__shutdown_tracer_provider()

        if not Client._is_dedicated_provider:
            # HACK: set global tracer provider to a proxy tracer provider back
            opentelemetry.trace._TRACER_PROVIDER = None  # type: ignore
            opentelemetry.trace._TRACER_PROVIDER_SET_ONCE = Once()  # type: ignore

    # Ensure provider/exporter exist after setting the key
    if (
        value
        and not Client._disable_sending
        and not Client._skip_open_telemetry_setup
    ):
        self.__setup_tracer_provider()

    if value:
        self._setup_rest_api_client()

@property
def disable_sending(self) -> bool:
    """Get whether sending is disabled."""
    return Client._disable_sending

@property
def rest_api_client(self) -> LangWatchApiClient:
    """Get the REST API client for the client."""
    if Client._rest_api_client is None:
        raise RuntimeError(
            "REST API client not initialized. Call _setup_rest_api_client() first."
        )
    return Client._rest_api_client

@property
def skip_open_telemetry_setup(self) -> bool:
    """Get whether OpenTelemetry setup is skipped."""
    return Client._skip_open_telemetry_setup

@property
def prompts_path(self) -> Optional[str]:
    """Get the base path for local prompt files."""
    return Client._prompts_path

@disable_sending.setter
def disable_sending(self, value: bool) -> None:
    """Set whether sending is disabled. Spans are still created; the exporter conditionally drops them."""
    if Client._disable_sending == value:
        return

    # force flush the tracer provider before changing the disable_sending flag
    if Client._tracer_provider and not Client._skip_open_telemetry_setup:
        Client._tracer_provider.force_flush()

    Client._disable_sending = value

def acquire_disable_sending(self) -> None:
    """Refcount-based gate used by `langwatch.trace(disable_sending=True)`.

    Each call increments the refcount and forces sending disabled. Pairs
    with `release_disable_sending`. Concurrency-safe (issue #3981): an
    overlapping default-sending trace will not flip the flag back on
    while another trace still holds the disable refcount.
    """
    with Client._disable_sending_lock:
        if Client._disable_sending_refcount == 0:
            Client._disable_sending_user_baseline = Client._disable_sending
        Client._disable_sending_refcount += 1
        if not Client._disable_sending:
            # Bypass the public setter's force_flush — we want to start
            # dropping spans immediately, not flush pending traffic that
            # was queued under the prior baseline.
            Client._disable_sending = True

def release_disable_sending(self) -> None:
    """Pair with `acquire_disable_sending`. Decrement the refcount; when
    it returns to zero, restore the user-set baseline value.
    """
    with Client._disable_sending_lock:
        if Client._disable_sending_refcount == 0:
            # Already released — defensive no-op; an unbalanced release
            # should not corrupt the baseline.
            return
        Client._disable_sending_refcount -= 1
        if Client._disable_sending_refcount == 0:
            baseline = Client._disable_sending_user_baseline
            if Client._disable_sending != baseline:
                if (
                    Client._tracer_provider
                    and not Client._skip_open_telemetry_setup
                ):
                    Client._tracer_provider.force_flush()
                Client._disable_sending = baseline

def __shutdown_tracer_provider(self) -> None:
    """Shuts down the current tracer provider, including flushing."""
    if not self._tracer_provider:
        return

    if Client._is_dedicated_provider:
        self.__detach_langwatch_processor()
        return

    if self._flush_on_exit:
        try:
            atexit.unregister(self._tracer_provider.force_flush)
        except ValueError:
            pass  # atexit handler was never registered or already unregistered

    force_flush = getattr(self._tracer_provider, "force_flush", None)
    if callable(force_flush):
        if self._debug:
            logger.debug("Forcing flush of tracer provider before shutdown.")
        force_flush()

    if Client._debug:
        logger.debug("Shutting down tracer provider.")
    if Client._tracer_provider is not None:
        Client._exporter_attached_providers.discard(id(Client._tracer_provider))
        Client._tracer_provider.shutdown()
    Client._tracer_provider = None

def __detach_langwatch_processor(self) -> None:
    """Remove and shut down only our processor from a user-owned provider."""
    if Client._langwatch_processor is not None:
        Client._langwatch_processor.force_flush()
        Client._langwatch_processor.shutdown()
        try:
            multi = Client._tracer_provider._active_span_processor  # type: ignore[union-attr]
            old = Client._langwatch_processor

    # Check your singleton's disable flag
    client = get_instance()
    if client and client.disable_sending:
        # Drop all spans - return success without sending
        return SpanExportResult.SUCCESS

    # Normal export
    return self.wrapped_exporter.export(spans)  # type: ignore

def shutdown(self) -> None:
    return self.wrapped_exporter.shutdown()

def force_flush(self, timeout_millis: Optional[int] = 30000) -> bool:
    client = get_instance()
    if client and client.disable_sending:
        return True  # Nothing to flush
    # Handle None case by providing default value
    actual_timeout = timeout_millis if timeout_millis is not None else 30000
    return self.wrapped_exporter.force_flush(actual_timeout)

"""Module for storing global state."""

import os
from typing import Optional
from .types import LangWatchClientProtocol

# Singleton instance of the client
__instance: Optional[LangWatchClientProtocol] = None

def get_instance() -> Optional[LangWatchClientProtocol]:
    """Get the current LangWatch client instance."""
    return __instance

def set_instance(client: LangWatchClientProtocol) -> None:
    """Set the current LangWatch client instance."""
    global __instance
    __instance = client

def get_endpoint() -> str:
    """Get the current endpoint URL of the LangWatch client."""
    if __instance is None:
        return os.getenv("LANGWATCH_ENDPOINT") or "REDACTED"
    return __instance.endpoint_url

def get_api_key() -> str:
    """Get the current API key of the LangWatch client."""
    if __instance is None:
        return os.getenv("LANGWATCH_API_KEY", "")
    return __instance.api_key

def set_api_key(api_key: str) -> None:
    """Set the current API key of the LangWatch client."""
    instance = get_instance()
    if instance is None:
        raise RuntimeError("LangWatch client has not been initialized. Call setup() first.")
    instance.api_key = api_key

